/* prefetch operation */
static const char* prfop_lookup(unsigned prfop)
{
	switch (prfop)
	{
	case 0b00000:
		return "pldl1keep";
	case 0b00001:
		return "pldl1strm";
	case 0b00010:
		return "pldl2keep";
	case 0b00011:
		return "pldl2strm";
	case 0b00100:
		return "pldl3keep";
	case 0b00101:
		return "pldl3strm";
	case 0b00110:
		return "#6";
	case 0b00111:
		return "#7";
	case 0b01000:
		return "plil1keep";
	case 0b01001:
		return "plil1strm";
	case 0b01010:
		return "plil2keep";
	case 0b01011:
		return "plil2strm";
	case 0b01100:
		return "plil3keep";
	case 0b01101:
		return "plil3strm";
	case 0b01110:
		return "#14";
	case 0b01111:
		return "#15";
	case 0b10000:
		return "pstl1keep";
	case 0b10001:
		return "pstl1strm";
	case 0b10010:
		return "pstl2keep";
	case 0b10011:
		return "pstl2strm";
	case 0b10100:
		return "pstl3keep";
	case 0b10101:
		return "pstl3strm";
	case 0b10110:
		return "#22";
	case 0b10111:
		return "#23";
	case 0b11000:
		return "#24";
	case 0b11001:
		return "#25";
	case 0b11010:
		return "#26";
	case 0b11011:
		return "#27";
	case 0b11100:
		return "#28";
	case 0b11101:
		return "#29";
	case 0b11110:
		return "#30";
	case 0b11111:
		return "#31";
	default:
		return "error";
	}
}

