/* hint.xml */
int HINT(context *ctx, Instruction *instr)
{
	int rc = DECODE_STATUS_UNMATCHED;
	/* class iclass_system */
	/* 110|101|01000000110010|CRm=xxxx|op2=xxx|11111 */
	if((INSWORD & 0xFFFFF01F)==0xD503201F) {
		decode_fields32(ENC_HINT_HM_HINTS, ctx, instr);
		if(!((ctx->CRm<<3)|ctx->op2)) {
			ctx->op = SystemHintOp_NOP;
		}
		else if(((ctx->CRm<<3)|ctx->op2)==1) {
			ctx->op = SystemHintOp_YIELD;
		}
		else if(((ctx->CRm<<3)|ctx->op2)==2) {
			ctx->op = SystemHintOp_WFE;
		}
		else if(((ctx->CRm<<3)|ctx->op2)==3) {
			ctx->op = SystemHintOp_WFI;
		}
		else if(((ctx->CRm<<3)|ctx->op2)==4) {
			ctx->op = SystemHintOp_SEV;
		}
		else if(((ctx->CRm<<3)|ctx->op2)==5) {
			ctx->op = SystemHintOp_SEVL;
		}
		else if(((ctx->CRm<<3)|ctx->op2)==6) {
			if(!HaveDGH()) {
				EndOfDecode(Decode_NOP);
			}
			ctx->op = SystemHintOp_DGH;
		}
		else if(((ctx->CRm<<3)|ctx->op2)==7) {
			SEE /* XPACLRI */;
		}
		else if((((ctx->CRm<<3)|ctx->op2)&0x78)==8) {
			if(!ctx->op2) {
				SEE /* PACIA1716 */;
			}
			else if(ctx->op2==2) {
				SEE /* PACIB1716 */;
			}
			else if(ctx->op2==4) {
				SEE /* AUTIA1716 */;
			}
			else if(ctx->op2==6) {
				SEE /* AUTIB1716 */;
			}
			else {
				EndOfDecode(Decode_NOP);
			}
		}
		else if(((ctx->CRm<<3)|ctx->op2)==0x10) {
			if(!HaveRAS()) {
				EndOfDecode(Decode_NOP);
			}
			ctx->op = SystemHintOp_ESB;
		}
		else if(((ctx->CRm<<3)|ctx->op2)==0x11) {
			if(!HaveSPE()) {
				EndOfDecode(Decode_NOP);
			}
			ctx->op = SystemHintOp_PSB;
		}
		else if(((ctx->CRm<<3)|ctx->op2)==0x12) {
			if(!HaveTRF()) {
				EndOfDecode(Decode_NOP);
			}
			ctx->op = SystemHintOp_TSB;
		}
		else if(((ctx->CRm<<3)|ctx->op2)==0x13) {
			if(!HaveGCS()) {
				EndOfDecode(Decode_NOP);
			}
			ctx->op = SystemHintOp_GCSB;
		}
		else if(((ctx->CRm<<3)|ctx->op2)==0x14) {
			ctx->op = SystemHintOp_CSDB;
		}
		else if(((ctx->CRm<<3)|ctx->op2)==0x16) {
			if(!HaveCLRBHB()) {
				EndOfDecode(Decode_NOP);
			}
			ctx->op = SystemHintOp_CLRBHB;
		}
		else if((((ctx->CRm<<3)|ctx->op2)&0x78)==0x18) {
			if(!ctx->op2) {
				SEE /* PACIAZ */;
			}
			else if(ctx->op2==1) {
				SEE /* PACIASP */;
			}
			else if(ctx->op2==2) {
				SEE /* PACIBZ */;
			}
			else if(ctx->op2==3) {
				SEE /* PACIBSP */;
			}
			else if(ctx->op2==4) {
				SEE /* AUTIAZ */;
			}
			else if(ctx->op2==5) {
				SEE /* AUTIASP */;
			}
			else if(ctx->op2==6) {
				SEE /* AUTIBZ */;
			}
			else if(ctx->op2==7) {
				SEE /* AUTIBSP */;
			}
		}
		else if((((ctx->CRm<<3)|ctx->op2)&0x79)==0x20) {
			if(!HaveBTI()) {
				EndOfDecode(Decode_NOP);
			}
			SetBTypeCompatible(BTypeCompatible_BTI(SLICE(ctx->op2,2,1), ctx->pstate_btype));
			ctx->op = SystemHintOp_BTI;
		}
		else if(((ctx->CRm<<3)|ctx->op2)==0x27) {
			SEE /* PACM */;
		}
		else if(((ctx->CRm<<3)|ctx->op2)==0x28) {
			if(!HaveCHK()) {
				EndOfDecode(Decode_NOP);
			}
			ctx->op = SystemHintOp_CHKFEAT;
		}
		else if((((ctx->CRm<<3)|ctx->op2)&0x7e)==0x30) {
			if(!HavePCDPHINT()) {
				EndOfDecode(Decode_NOP);
			}
			ctx->stream = SLICE(ctx->op2,0,0)==1;
			ctx->op = SystemHintOp_STSHH;
		}
		else if((((ctx->CRm<<3)|ctx->op2)&0x7e)==0x32) {
			if(!HaveCMH()) {
				EndOfDecode(Decode_NOP);
			}
			ctx->priority = SLICE(ctx->op2,0,0)==1;
			ctx->op = SystemHintOp_SHUH;
		}
		else if(((ctx->CRm<<3)|ctx->op2)==0x34) {
			if(!HaveCMH()) {
				EndOfDecode(Decode_NOP);
			}
			ctx->op = SystemHintOp_STCPH;
		}
		else {
			EndOfDecode(Decode_NOP);
		}
		OK(ENC_HINT_HM_HINTS);
	}
	return rc;
}

