	ctx->t = UINT(ctx->Rt);
	ctx->n = UINT(ctx->Rn);
	ctx->m = UINT(ctx->Rm);
	ctx->datasize = (8) << (ctx->scale);
	ctx->nontemporal = false;
	ctx->tagchecked = true;
	return rc;
