{
	int rc = DECODE_STATUS_UNMATCHED;
	/* class iclass_system */
	/* 110|101|0101|L=0|1|o0=x|op1=xxx|CRn=xxxx|CRm=xxxx|op2=xxx|Rt=xxxxx */
	if((INSWORD & 0xFFF00000)==0xD5500000) {
		decode_fields32(ENC_MSRR_SR_SYSTEMMOVEPR, ctx, instr);
		if(!HaveSYSREG128()) {
			EndOfDecode(Decode_UNDEF);
		}
		if(SLICE(ctx->Rt,0,0)==1) {
			EndOfDecode(Decode_UNDEF);
		}
		ctx->t = UINT(ctx->Rt);
		ctx->t2 = UINT(ctx->Rt+1);
		ctx->sys_L = ctx->L;
		ctx->sys_op0 = ((1<<1)|ctx->o0);
		ctx->sys_op1 = ctx->op1;
		ctx->sys_op2 = ctx->op2;
		ctx->sys_crn = ctx->CRn;
		ctx->sys_crm = ctx->CRm;
		OK(ENC_MSRR_SR_SYSTEMMOVEPR);
	}
	return rc;
}

/* msr_imm.xml */
int MSR_imm(context *ctx, Instruction *instr)
{
	int rc = DECODE_STATUS_UNMATCHED;
	/* class iclass_system */
	/* 110|101|0100000|op1=xxx|0100|CRm=xxxx|op2=xxx|Rt=11111 */
	if((INSWORD & 0xFFF8F01F)==0xD500401F) {
		decode_fields32(ENC_MSR_SI_PSTATE, ctx, instr);
		if(ctx->op1==0 && ctx->op2==0) {
			SEE /* CFINV */;
		}
		if(ctx->op1==0 && ctx->op2==1) {
			SEE /* XAFLAG */;
		}
		if(ctx->op1==0 && ctx->op2==2) {
			SEE /* AXFLAG */;
		}
		ctx->need_secure = false;
		if(!(ctx->op1&6)) {
			ctx->min_EL = EL1;
		}
		else if(ctx->op1==2) {
			ctx->min_EL = EL1;
		}
		else if(ctx->op1==3) {
			ctx->min_EL = EL0;
		}
		else if(ctx->op1==4) {
			ctx->min_EL = EL2;
		}
		else if(ctx->op1==5) {
			if(!HaveVHE()) {
				EndOfDecode(Decode_UNDEF);
			}
			ctx->min_EL = EL2;
		}
		else if(ctx->op1==6) {
			ctx->min_EL = EL3;
		}
		else if(ctx->op1==7) {
			ctx->min_EL = EL1;
			ctx->need_secure = true;
		}
		ctx->operand = ctx->CRm;
		if(((ctx->op1<<3)|ctx->op2)==3) {
			if(!HaveUAO()) {
				EndOfDecode(Decode_UNDEF);
			}
			ctx->field = PSTATEField_UAO;
		}
		else if(((ctx->op1<<3)|ctx->op2)==4) {
			if(!HavePAN()) {
				EndOfDecode(Decode_UNDEF);
			}
			ctx->field = PSTATEField_PAN;
		}
		else if(((ctx->op1<<3)|ctx->op2)==5) {
			ctx->field = PSTATEField_SP;
		}
		else if(((ctx->op1<<3)|ctx->op2)==8) {
			if(!(ctx->CRm&14)) {
				if(!HaveNMI()) {
					EndOfDecode(Decode_UNDEF);
				}
				ctx->field = PSTATEField_ALLINT;
			}
			else if((ctx->CRm&14)==2) {
				if(!HaveEBEP()) {
					EndOfDecode(Decode_UNDEF);
				}
				ctx->field = PSTATEField_PM;
			}
			else {
				EndOfDecode(Decode_UNDEF);
			}
		}
		else if(((ctx->op1<<3)|ctx->op2)==0x1a) {
			if(!HaveDIT()) {
				EndOfDecode(Decode_UNDEF);
			}
			ctx->field = PSTATEField_DIT;
		}
		else if(((ctx->op1<<3)|ctx->op2)==0x1b) {
			if((ctx->CRm&14)==2) {
				if(!HaveSME()) {
					EndOfDecode(Decode_UNDEF);
				}
				ctx->field = PSTATEField_SVCRSM;
			}
			else if((ctx->CRm&14)==4) {
				if(!HaveSME()) {
					EndOfDecode(Decode_UNDEF);
				}
				ctx->field = PSTATEField_SVCRZA;
			}
			else if((ctx->CRm&14)==6) {
				if(!HaveSME()) {
					EndOfDecode(Decode_UNDEF);
				}
				ctx->field = PSTATEField_SVCRSMZA;
			}
			else {
				EndOfDecode(Decode_UNDEF);
			}
		}
		else if(((ctx->op1<<3)|ctx->op2)==0x1c) {
			if(!HaveMTE()) {
				EndOfDecode(Decode_UNDEF);
			}
			ctx->field = PSTATEField_TCO;
		}
		else if(((ctx->op1<<3)|ctx->op2)==0x1e) {
			ctx->field = PSTATEField_DAIFSet;
		}
		else if(((ctx->op1<<3)|ctx->op2)==0x1f) {
			ctx->field = PSTATEField_DAIFClr;
		}
		else if(((ctx->op1<<3)|ctx->op2)==0x19) {
			if(!HaveSSBS()) {
				EndOfDecode(Decode_UNDEF);
			}
			ctx->field = PSTATEField_SSBS;
		}
		else {
			EndOfDecode(Decode_UNDEF);
		}
		/* regular aliases */
		if(ctx->op1==3 && ((ctx->CRm&9)==1) && ctx->op2==3) return SMSTART_MSR_imm(ctx, instr);
		if(ctx->op1==3 && (!(ctx->CRm&9)) && ctx->op2==3) return SMSTOP_MSR_imm(ctx, instr);
		if(!(ctx->op1==0 && (!(ctx->op2&6) || ctx->op2==2))) OK(ENC_MSR_SI_PSTATE);
	}
	return rc;
}

