		ctx->sys_op2 = ctx->op2;
		ctx->sys_crn = ctx->CRn;
		ctx->sys_crm = ctx->CRm;
		/* regular aliases */
		if(ctx->op1==6 && ctx->CRn==7 && ctx->CRm==0 && ctx->op2==0) return APAS_SYS(ctx, instr);
		if(ctx->CRn==7 && ((ctx->CRm&14)==8) && SysOp(ctx->op1,7,ctx->CRm,ctx->op2)==Sys_AT) return AT_SYS(ctx, instr);
